from pathlib import Path
import json, hashlib
base=Path('ONTOLOGY-depo/integrations/curator/1.0.0')
def write(name,value):
 p=base/name;p.write_text(json.dumps(value,indent=2,sort_keys=True)+'\n')
sources={'charter':('CURATOR.md','line:1'),'policy':('curator.yaml','json:/project'),'session':('curator-session.yaml','json:/mode'),'actions':('.agents/skills/curate/ACTIONS.md','section:Curator actions'),'commands':('.agents/skills/curate/references/commands.md','line:1'),'catch-up':('.agents/skills/curate/references/session-maintenance.md','line:1'),'task':('.agents/skills/agent-task/SKILL.md','line:1'),'memory':('.agents/skills/memory/SKILL.md','line:1'),'ontology':('.agents/skills/ontology/SKILL.md','line:1'),'integration':('.agents/skills/curate/scripts/curator_integration.py','line:1'),'recovery':('.agents/skills/curate/scripts/curator_recovery.py','line:1'),'products':('.agents/skills/curate/scripts/curator_products.py','line:1'),'logs':('.agents/skills/curate/scripts/curator_logs.py','line:1'),'learning':('.agents/skills/what-did-you-learn/SKILL.md','line:1'),'role-index':('Roles/INDEX.md','line:1')}
owners={'curate':{'skill':'curate','role':'curator-manager'},'task':{'skill':'agent-task','role':'task-manager'},'memory':{'skill':'memory','role':'knowledge-curator'},'ontology':{'skill':'ontology','role':'knowledge-curator'},'integration':{'skill':'curate','role':'improvement-maintenance'},'products':{'skill':'ontology','role':'knowledge-curator'},'logs':{'skill':'curate','role':'curator-manager'}}
functions=[('status','Inspect bounded selected policy and current metadata without repair or model analysis.','curate','policy','policy-status','selected-project','read-scope','actions'),('validate','Validate selected policy structure without admitting or performing maintenance.','curate','policy','validation-result','selected-project','read-scope','actions'),('review','Review scoped metadata or authenticated bounded source ownership; no canonical writes.','curate','review-request','review-findings','selected-source-scope','current-owner','commands'),('update','Route exact reviewed updates to existing integration, memory, ontology or derived-product owner.','integration','reviewed-change','owner-receipt','selected-owner-targets','current-grant','commands'),('correct','Route exact reviewed integration or canonical lifecycle corrections through the current owner.','integration','reviewed-correction','owner-receipt','selected-owner-targets','current-grant','commands'),('retry','Recover the original exact operation and prior journal through its known owner recovery pair.','integration','original-intent','owner-receipt','original-targets','current-grant','recovery'),('pause','Pause existing Task lifecycle with interruption and reconciliation of current native write owners.','task','task-selection','lifecycle-result','selected-task','current-owner','task'),('resume','Resume existing Task through its lifecycle owner after current native ownership reconciliation.','task','task-selection','lifecycle-result','selected-task','current-owner','task'),('tick','Dispatch selected maintenance within cadence and budget through an actual host actor or Broker callback.','curate','selected-dispatch','owner-receipt','selected-owner-targets','live-actor-budget','commands'),('session-catch-up','Collect changed-input observations at session start or return and retain deliveries; current-owner evaluation and selected dispatch are separate.','curate','changed-input-observation','retained-delivery','selected-project','session-enabled-budget','catch-up'),('log-register','Register an exact permitted log source using the bounded existing log owner protocol.','logs','log-selection','registered-log','selected-log','current-owner','logs'),('log-list','List registered log metadata within the selected bounds.','logs','log-selection','log-metadata','selected-log','read-scope','logs'),('log-summary','Read a bounded summary of a registered log while preserving full underlying logs.','logs','log-selection','log-summary','selected-log','read-scope','logs'),('log-query','Query bounded registered log records using exact filters and pagination.','logs','log-query','log-results','selected-log','read-scope','logs')]
write('recipe.json',{'schema_version':1,'edition':'curator-ontology-1.0.0','namespace_suffix':'curator-','owners':owners,'functions':[dict(zip(('id','definition','owner','input','output','scope','prerequisite','source'),f)) for f in functions]})
write('locators.json',{'schema_version':1,'sources':{k:{'path':p,'locator':l} for k,(p,l) in sources.items()}})
write('competency.json',{'schema_version':1,'functions':[f[0] for f in functions],'required_edges':['consumes','produces','maintains','coordinatesOwner','triggeredBy','requiresPrerequisite']})
write('manifest.json',{'schema_version':1,'edition':'curator-ontology-1.0.0','files':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(base.glob('*.json')) if p.name!='manifest.json'}})
